// level, so each aura below opens on exactly one of them.
const AURA_PROTECTION_BONUSES = [1, 2, 3, 4, 5];
const auraProtection = (bonus, far) => ({
  distance: far ? 30 : 10,
  side: "allies",
  self: true,
  conditions: [`aura_protection_${bonus}`],
  when: {
    value: { derived: "aura_protection_code" },
    atLeast: bonus + (far ? 10 : 0),
    ...(bonus < 5 || !far ? { atMost: bonus + (far ? 10 : 0) } : {}),
  },
});
// Aura of Courage, Aura of Devotion: "you and friendly creatures within 10 feet of you can't be
