const auraByLevel = (condition) =>
  [
    [10, { atMost: 17 }],
    [30, { atLeast: 18 }],
  ].map(([distance, levels]) => ({
    distance,
    side: "allies",
    self: true,
    conditions: [condition],
    when: { value: { field: "level_paladin" }, ...levels },
  }));
