const ARMOR_TRAINING = Object.fromEntries(
  ["light", "medium", "heavy", "shield"].map((kind) => [
    kind,
    {
      value: { derived: `${kind}_${kind === "shield" ? "" : "armor_"}levels` },
      atLeast: 1,
      otherwise: { keepsOn: ["armor_untrained"] },
    },
  ]),
);

/** A cost in gold pieces, as the fixture writes it, in the largest of the SRD's own coins (gp, sp,
 *  cp) that says it whole. Undefined for nothing.
 *
 *  ponytail: a price is a whole number of the smallest coin, so the SRD's sling bullets ("Sling
 *  bullets (20) 4 cp", a fifth of a copper each) stay at the fixture's 1 cp each, five times the
 *  SRD's price; the README says so. A bundle item that is spent a piece at a time is the upgrade. */
function itemCost(gold, label) {
  const copper = Math.round(Number(gold) * 100);
  if (!Number.isFinite(copper) || copper < 0) fail(`${label} has a cost this converter cannot read: ${gold}`);
  if (Math.abs(copper - Number(gold) * 100) > 1e-6) fail(`${label} costs part of a copper piece: ${gold}`);
  return costInCopper(copper);
}

/** A price in copper pieces, said in the largest of gp, sp and cp that says it whole. */
function costInCopper(copper) {
  if (copper === 0) return undefined;
  if (copper % 100 === 0) return { amount: copper / 100, unit: "gp" };
  if (copper % 10 === 0) return { amount: copper / 10, unit: "sp" };
  return { amount: copper, unit: "cp" };
}

const COIN_COPPER = new Map([
  ["cp", 1],
  ["sp", 10],
  ["ep", 50],
  ["gp", 100],
  ["pp", 1000],
]);
const copperOf = (cost) => (cost ? cost.amount * COIN_COPPER.get(cost.unit) : 0);

// The package's own prices. SRD 5.1 prices no magic item but the potion of healing (50 gp), so these
// are written down rather than read. They follow the APPROACH of the community guide "Sane Magical
// Prices" (by Saidoro): what an item does for its holder sets its price, inside what its rarity says
// about how hard it is to find. That guide's own price table carries no license and is not used; every
// number below is this package's.
//
// - A lasting item costs its rarity's price for its use. One that wins fights (a magic weapon or armor,
//   a bonus to Armor Class, saves or an ability, a resistance, a power that harms, heals or holds a
//   foe) costs two and a half times one that helps elsewhere (travel, the senses, disguise, storage).
//   From uncommon up, each rarity step costs four times the last; a common item is a third of an
//   uncommon one, so a potion of healing keeps the SRD's 50 gp.
// - A game-changing item costs four times a fighting one of its rarity, a step up the ladder: it
//   changes what the whole game can be, and the Game Master may well keep it out.
// - An item that brings creatures costs five gold pieces a point of their experience (SRD 5.1's own
//   measure of a creature, here a hireling's wage), and never less than a helping item of its rarity.
// - Something used up (a potion, an oil, an arrow, a bead or a pinch of dust) costs a tenth of a
//   lasting item of its rarity and use, times the uses it holds. A book whose reading leaves something
//   that lasts (a +2 to an ability for good, a golem) is priced as lasting.
// - A spell scroll doubles a level, from 25 gp for a cantrip to 12,800 gp for a level 9 spell.
// - A magic weapon or armor adds the price of the SRD one it is made of, and a price is rounded to a
//   whole gold piece.
// - Never for sale: an artifact, a wish (the deck of many things aside, by the user's ruling), the
//   efreeti bottle, and a cursed item with nothing to pass for. A wild chance item is priced and carries
//   the warning an honest seller gives (`RISKY`); a fake costs what it truly is worth and passes for
//   another item (`FAKES`), which only a dishonest seller sells it as.
const LASTING_PRICE_GP = new Map([
  ["common", 500],
  ["uncommon", 1500],
  ["rare", 6000],
  ["very_rare", 24000],
  ["legendary", 96000],
]);
