function itemCanCast(mechanics) {
  return (
    !!mechanics &&
    (SCROLL_USE_KINDS.has(mechanics.kind) ||
      curesOnly(mechanics) ||
      placesOnly(mechanics) ||
      dispelsOnly(mechanics) ||
      // A staff's Passwall and Plane Shift (0.256.0), as their scrolls carry them.
      teleportsOnly(mechanics) ||
      breaksLayersOnly(mechanics)) &&
    mechanics.reaction === undefined
  );
}
/** A staff's or wand's cast of one spell: the spell's own mechanics, at the item's DC or its holder's,
 *  for its charges, at a printed higher level, or a level up a charge (`stepMax` more). */
function itemSpellCast(spell, charges, { dc, level, stepMax } = {}) {
  const mechanics = spell.mechanics;
  const steps = level ? level - spell.filters.level : 0;
  const fields = scrollUseFields(mechanics, level ?? spell.filters.level);
  if (steps) {
    fields.amount = steppedAmount(mechanics.amount, mechanics.perCostStep, steps);
    if (mechanics.targetsPerCostStep)
      fields.targetCount = (mechanics.targetCount ?? 1) + mechanics.targetsPerCostStep * steps;
    if (mechanics.area?.sizePerCostStep)
      fields.area = { ...fields.area, size: fields.area.size + mechanics.area.sizePerCostStep * steps };
  }
  const saves = !!(mechanics.save || mechanics.applies?.some((each) => each.saveEnds));
  const step =
    stepMax && (mechanics.perCostStep || mechanics.targetsPerCostStep)
      ? compact({ max: stepMax, amount: mechanics.perCostStep, targets: mechanics.targetsPerCostStep })
      : undefined;
  if (stepMax && !step) fail(`${spell.label} has nothing to add a charge`);
  return compact({
    kind: curesOnly(mechanics) ? "heal" : mechanics.kind,
    budget: BUDGET_ACTION,
    casts: SPELL_CATALOG,
    ...fields,
    attackRoll: mechanics.attackRoll,
    toHit: mechanics.attackRoll
      ? dc === undefined
        ? { sheetBonus: { derived: "spell_attack" } }
        : undefined
      : undefined,
    saveDifficulty: saves && dc !== undefined ? dc : undefined,
    sheetDifficulty: saves && dc === undefined ? { derived: "spell_save_dc" } : undefined,
    // 1.271: an item cast "using your ... spellcasting ability modifier" adds it, as the spell does.
    amountAdd: dc === undefined ? mechanics.amountAdd : undefined,
    // Plane Shift's teleport (1.276) and Passwall's breaking of a layered wall (1.494), as a scroll's.
    teleport: mechanics.teleport,
    calls: mechanics.calls,
    endsLayers: mechanics.endsLayers,
    endsLayersAs: mechanics.endsLayers ? `${SPELL_CATALOG}/${spell.id}` : undefined,
    charges,
    chargeStep: step,
  });
}

/** One magic item's text, its escaped line breaks and Markdown emphasis taken out. */
function magicText(desc) {
  return oneLine(
    String(desc)
      .replace(/\\n|\n/gu, " ")
      .replace(/\*\*_?|_?\*\*|_/gu, ""),
  );
}

// Reuse a spell's resolved effect, as scrolls do, without spending the holder's spell slots.
function spellItemUse(mechanics, dc, toHit) {
  return compact({
    kind: mechanics.kind,
    budget: BUDGET_ACTION,
    ...scrollUseFields(mechanics),
    // A save that ends a condition (Ray of Enfeeblement's) is against the scroll's DC too.
    saveDifficulty: castsAtDc(mechanics) ? dc : undefined,
    attackRoll: mechanics.attackRoll,
    toHit: mechanics.attackRoll ? toHit : undefined,
  });
}

