        add("modifiers", [{ to: "saves", flat: 1 }]);
        item.charges = { max: 6, recharge: { rests: [DAWN_REST], amount: { dice: "1d6" } } };
        item.stack = 1;
        item.use = { ...itemSpellCast(spellById.get("magic-missile"), 1, { level: 5 }), label: "Magic Missile" };
        // 0.293.0 (1.627): "While you wear the robe, you can use an action to enter the Astral Plane along with
