  if (mechanics.kind !== "utility" || mechanics.area || mechanics.zone) fail(`${pk} reads as more than a utility now`);
  for (const condition of WARD_CANT_GIVE)
    if (!APPLIED_CONDITION_SET.has(condition)) fail(`${pk} keeps off "${condition}", which the sheet has not`);
