const grantSpells = (feature, spellClass, rows, expected) => {
  if (rows.length !== expected) fail(`${feature.id} reads ${rows.length} rows of its table, not ${expected}`);
  feature.filters = { ...feature.filters, spell_class: spellClass };
  for (const { names } of rows)
    for (const name of names) {
      const spell =
        spellByName.get(name.toLowerCase()) ?? fail(`${feature.id} grants "${name}", no spell of the catalog`);
      spell.filters.granted_ids = [...new Set([...spell.filters.granted_ids, feature.id, `of_${spellClass}`])].sort();
    }
};
