// The bulette's Standing Leap (0.333.0, 1.716): "The bulette's long jump is up to 30 ft. and its high jump is up to
// 15 ft., with or without a running start."
{
  const bulette = creatures.find((one) => one.id === "bulette") ?? fail("no bulette for Standing Leap");
  const leap = (creatureTraits.get("srd_bulette") ?? []).find(({ pk }) => pk === "srd_bulette_standing-leap");
  if (
    oneLine(plainText(leap?.fields.desc ?? "")) !==
    "The bulette's long jump is up to 30 ft. and its high jump is up to 15 ft., with or without a running start."
  )
    fail("the bulette's Standing Leap no longer reads as it did");
  bulette.creature.jump = { long: 30, high: 15, withoutRunUp: true };
}
// The frogs' and the toad's Standing Leap and the lion's Running Leap (0.400.0, 1.716), and the vampires' Spider
// Climb as the climbing speed it is (1.395): each read off its trait.
for (const [id, trait, printed, change] of [
  [
    "frog",
    "standing-leap",
    "The frog's long jump is up to 10 ft. and its high jump is up to 5 ft., with or without a running start.",
    (block) => {
      block.jump = { long: 10, high: 5, withoutRunUp: true };
    },
  ],
  [
    "giant-frog",
    "standing-leap",
    "The frog's long jump is up to 20 ft. and its high jump is up to 10 ft., with or without a running start.",
    (block) => {
      block.jump = { long: 20, high: 10, withoutRunUp: true };
    },
  ],
  [
    "giant-toad",
    "standing-leap",
    "The toad's long jump is up to 20 ft. and its high jump is up to 10 ft., with or without a running start.",
    (block) => {
      block.jump = { long: 20, high: 10, withoutRunUp: true };
    },
  ],
  // The high jump is the ordinary one, 3 + its Strength modifier of +3.
  [
    "lion",
    "running-leap",
    "With a 10-foot running start, the lion can long jump up to 25 ft..",
    (block) => {
      block.jump = { long: 25, high: 6 };
    },
  ],
  ...["vampire", "vampire-spawn"].map((vampire) => [
    vampire,
    "spider-climb",
    "The vampire can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check.",
    (block) => {
      if (block.speeds?.climb !== undefined) fail(`${vampire} already climbs`);
      block.speeds = { ...(block.speeds ?? {}), climb: block.speed };
    },
  ]),
]) {
  const block = creatures.find((one) => one.id === id)?.creature ?? fail(`no ${id} for its ${trait}`);
  const text = (creatureTraits.get(`srd_${id}`) ?? []).find(({ pk }) => pk === `srd_${id}_${trait}`);
  if (oneLine(plainText(text?.fields.desc ?? "")) !== printed) fail(`${id}'s ${trait} no longer reads as it did`);
  change(block);
}
