        if (/shillelagh/.test(action.id)) action.ability = base.ability;
        const mod = Math.floor((sheet.abilities[action.ability] - 10) / 2);
        action.toHit = proficiency + mod;
        if (mod) action.damage = { ...action.damage, flat: mod };
