// Who understands whom (0.276.0, Capability API 1.561): each creature's languages by label, off its stat
// block's Languages. "all" and "understands commands given in any language" understand every one, Druidic
// too; one with no Languages understands none; "the languages it knew in life" and any other it names none
// of are not known, so they are left unwritten and never keep it out. SRD 5.1, Languages: "Primordial
// includes the Auran, Aquan, Ignan, and Terran dialects. Creatures that know one of these dialects can
// communicate with those that know a different one", so each dialect is Primordial too. A people's own
// tongue no character learns (Gnoll, Otyugh, Sahuagin) is written as printed.
{
  const labels = languageEntries.map((one) => one.label);
  const dialects = ["Aquan", "Auran", "Ignan", "Terran"];
  const ownTongues = ["Gnoll", "Otyugh", "Sahuagin"];
  const records = new Map(
    srdOnly(await fixture("Creature.json"), "creature").map((one) => [one.pk.replace(/^srd_/u, ""), one.fields]),
  );
  for (const entry of creatures) {
    const fields = records.get(entry.id);
    if (!fields) continue;
    const desc = String(fields.languages_desc ?? "").trim();
    let known;
    if (/^all\b|any language/u.test(desc)) known = [...labels, "Druidic"];
    else if (desc === "" || desc === "-" || desc === "\u2014") known = [];
    else {
      known = labels.filter(
        (label) =>
          new RegExp(`\\b${label}\\b`, "iu").test(desc) ||
          (fields.languages ?? []).includes(languageEntries.find((one) => one.label === label).id),
      );
      if ((fields.languages ?? []).includes("druidic") || /\bDruidic\b/u.test(desc)) known.push("Druidic");
      const spoken = [...dialects, ...ownTongues].filter((tongue) => new RegExp(`\\b${tongue}\\b`, "u").test(desc));
      if (spoken.some((tongue) => dialects.includes(tongue)) && !known.includes("Primordial")) known.push("Primordial");
      known.push(...spoken);
      if (known.length === 0) {
        report.languagesUnread = [...(report.languagesUnread ?? []), `${entry.id}: ${desc}`];
        continue;
      }
    }
    entry.creature.languages = known;
  }
}
// Weapons that corrode on hitting (0.296.0, Capability API 1.551): the rust monster's Rust Metal and the
