for (const [id, printed, alternatives] of MULTIATTACK_ALTERNATIVES) {
  const block =
    creatures.find((one) => one.id === id)?.creature ?? fail(`no ${id} to give its Multiattack alternatives`);
  const sentence = oneLine(
    plainText(
      (creatureActions.get(`srd_${id}`) ?? []).find((one) => one.pk === `srd_${id}_multiattack`)?.fields.desc ?? "",
    ),
  );
  if (!sentence.includes(printed)) fail(`${id}'s Multiattack no longer says "${printed}"`);
  const last = block.actions.findLastIndex((one) => one.sequence);
  if (last < 0) fail(`${id} has no Multiattack to add alternatives beside`);
  const added = alternatives.map(([suffix, label, steps, extra]) => ({
    id: `multiattack_${suffix}`,
    name: `Multiattack (${label})`,
    budget: BUDGET_ACTION,
    sequence: steps.map((step) =>
      typeof step === "string"
        ? { action: step, times: 1 }
        : Array.isArray(step)
          ? { action: step[0], times: step[1] }
          : step,
    ),
    ...(extra ?? {}),
  }));
  for (const one of added) {
    if (block.actions.some((other) => other.id === one.id)) fail(`${id} already has a ${one.id}`);
    for (const step of one.sequence)
      if (!block.actions.some((other) => other.id === step.action && !other.sequence))
        fail(`${id} has no ${step.action} for ${one.id}`);
  }
  block.actions.splice(last + 1, 0, ...added);
  if (block.actions.length > CREATURE_MAX_ACTIONS) fail(`${id} now has more than ${CREATURE_MAX_ACTIONS} actions`);
}
// 0.403.0: the wyvern's claws only while it flies (whileFlying, Capability API 1.787): "While flying,
// it can use its claws in place of one other attack". The glabrezu's spell needs its spellcasting.
{
  const wyvern = creatures.find((one) => one.id === "wyvern")?.creature ?? fail("no wyvern");
  const claws = wyvern.actions.find((one) => one.id === "claws") ?? fail("the wyvern has no claws");
  claws.whileFlying = true;
  if (!wyvern.speeds?.fly) fail("the wyvern no longer flies");
  if (!creatures.find((one) => one.id === "glabrezu")?.creature?.spellcasting?.spells?.length)
    fail("the glabrezu casts no spells");
}
// 0.400.0: the succubus's Charm dominates, which puts its target on the fiend's side, so the Draining Kiss
// is aimed at either side (targets "any", Capability API 1.121); it still reaches only whom it charmed.
{
  const fiend = creatures.find((one) => one.id === "succubusincubus")?.creature ?? fail("no succubus");
  const kiss = fiend.actions.find((one) => one.id === "draining_kiss") ?? fail("the succubus has no Draining Kiss");
  if (!kiss.targetHolds?.fromSelf?.includes("dominated"))
    fail("the Draining Kiss no longer reaches whom the fiend dominates");
  kiss.targets = "any";
}
// The breath weapons of the dragons that exhale a gas (0.300.0, Capability API 1.652): the green's poisonous
// gas, the brass's sleep gas, the copper's slowing gas, the gold's weakening gas and the silver's paralyzing
// gas, which a Necklace of Adaptation gives advantage against.
const GAS_BREATHS = new Map([
  ["green", "Poison Breath"],
  ["brass", "Sleep Breath"],
  ["copper", "Slowing Breath"],
  ["gold", "Weakening Breath"],
  ["silver", "Paralyzing Breath"],
]);
let gasBreaths = 0;
for (const entry of creatures) {
  const color = /^(?:ancient|adult|young)-(\w+)-dragon$|^(\w+)-dragon-wyrmling$/u.exec(entry.id);
  const name = color && GAS_BREATHS.get(color[1] ?? color[2]);
  for (const action of name ? entry.creature.actions : [])
    if (action.name === name && action.save) {
      action.save.against = { ...action.save.against, qualities: ["gas"] };
      gasBreaths += 1;
    }
}
if (gasBreaths !== 20) fail(`${gasBreaths} gas breaths, not the 20 of the five dragons that exhale gas`);
// 0.414.0: the erinyes' variant, "Some erinyes carry a rope of entanglement ... When such an erinyes uses its
// Multiattack, the erinyes can use the rope in place of two of the attacks", an erinyes of its own beside the
// plain one, which keeps the SRD's stat block. The rope is the Rope of Entanglement's own Entangle (DC 15,
// 20 feet, cut free at AC 20 and 20 hit points).
{
  const printed =
    "When such an erinyes uses its Multiattack, the erinyes can use the rope in place of two of the attacks.";
  const plain = creatures.find((one) => one.id === "erinyes") ?? fail("no erinyes");
  const trait = plain.creature.traits?.find((one) => one.name === "Variant: Rope of Entanglement");
  if (!trait?.text?.includes(printed)) fail(`the erinyes' variant no longer says "${printed}"`);
  const rope =
    magicItems.find((one) => one.id === "rope-of-entanglement")?.item?.use ??
    fail("the Rope of Entanglement has no use");
  if (rope.range !== 20 || rope.saveDifficulty !== 15 || rope.applies?.[0]?.condition !== "rope_entangled")
    fail("the Rope of Entanglement reads differently now");
  const roped = structuredClone(plain);
  roped.id = "erinyes-rope-of-entanglement";
  roped.label = "Erinyes (rope of entanglement)";
  roped.summary = `${plain.summary} Carries a rope of entanglement.`.slice(0, SUMMARY_MAX);
  roped.creature.traits = roped.creature.traits.map((one) =>
    one === trait || one.name === trait.name ? { name: "Rope of Entanglement", text: trait.text } : one,
  );
  const actions = roped.creature.actions;
  if (!["longsword", "longbow"].every((id) => actions.some((one) => one.id === id)))
    fail("the erinyes no longer has its longsword and longbow");
  const last = actions.findLastIndex((one) => one.sequence);
  actions.splice(
    last + 1,
    0,
    {
      id: "multiattack_rope_melee",
      name: "Multiattack (longsword and rope)",
      budget: BUDGET_ACTION,
      sequence: [
        { action: "longsword", times: 1 },
        { action: "rope_of_entanglement", times: 1 },
      ],
    },
    {
      id: "multiattack_rope_ranged",
      name: "Multiattack (longbow and rope)",
      budget: BUDGET_ACTION,
      sequence: [
        { action: "longbow", times: 1 },
        { action: "rope_of_entanglement", times: 1 },
      ],
    },
  );
  actions.push({
    id: "rope_of_entanglement",
    name: "Rope of Entanglement",
    budget: BUDGET_ACTION,
    save: { save: "dex_save", difficulty: rope.saveDifficulty, onSuccess: "negates" },
    applies: structuredClone(rope.applies),
    targetCount: 1,
    range: rope.range,
    qualities: ["magical"],
  });
  if (actions.length > CREATURE_MAX_ACTIONS) fail(`the roped erinyes has more than ${CREATURE_MAX_ACTIONS} actions`);
  creatures.push(roped);
}
// A beast that only magic makes (Phantom Steed's steed, the figurines' goat of terror, giant fly and onyx
// mastiff) or the SRD's diseased variant of the giant rat is not one Wild Shape, Polymorph or a conjuring takes
// as a beast of its own (0.420.0): its type stays a beast in a fight, and only the bestiary's filter tells it.
{
  const kept = new Map([
    [PHANTOM_STEED, "Beast (magical)"],
    [GOAT_OF_TERROR, "Beast (magical)"],
    [GIANT_FLY, "Beast (magical)"],
    [ONYX_DOG, "Beast (magical)"],
    ["giant-rat-diseased", "Beast (variant)"],
  ]);
  for (const [id, type] of kept) {
    const creature = creatures.find((one) => one.id === id) ?? fail(`no ${id} to keep off the beasts`);
    if (creature.filters.type !== "Beast") fail(`${id} is no longer filed as a beast`);
    creature.filters.type = type;
  }
}
// What a humanoid foe has on it (Capability API 1.795, 0.420.0): the weapons its stat block attacks with,
// by the SRD weapon each action names, and ammunition for the ones that fire it. No armor: the party's
// loot takes the weapons only (Alyssa, 10-24), so a knight drops its greatsword, not 1,500 gp of plate.
// The SRD gives no count of arrows or bolts, so a launcher comes with ten. A form of a shapechanger is
// the creature it changed from, which carries the things.
{
  const weaponIds = new Map([
    ["club", "club"],
    ["dagger", "dagger"],
    ["greataxe", "greataxe"],
    ["greatclub", "greatclub"],
    ["greatsword", "greatsword"],
    ["handaxe", "handaxe"],
    ["javelin", "javelin"],
    ["longbow", "longbow"],
    ["longsword", "longsword"],
    ["mace", "mace"],
    ["maul", "maul"],
    ["morningstar", "morningstar"],
    ["quarterstaff", "quarterstaff"],
    ["rapier", "rapier"],
    ["scimitar", "scimitar"],
    ["shortbow", "shortbow"],
    ["shortsword", "shortsword"],
    ["sling", "sling"],
    ["spear", "spear"],
    ["war pick", "war-pick"],
    ["hand crossbow", "crossbow-hand"],
    ["heavy crossbow", "crossbow-heavy"],
    ["light crossbow", "crossbow-light"],
    ["trident", "trident"],
    ["whip", "whip"],
    ["battleaxe", "battleaxe"],
    ["glaive", "glaive"],
    ["halberd", "halberd"],
    ["lance", "lance"],
    ["pike", "pike"],
    ["warhammer", "warhammer"],
    ["flail", "flail"],
    ["light hammer", "light-hammer"],
    ["sickle", "sickle"],
    ["blowgun", "blowgun"],
    ["net", "net"],
  ]);
  const AMMUNITION = new Map([
    ["longbow", "arrow-bow"],
    ["shortbow", "arrow-bow"],
    ["crossbow-hand", "crossbow-bolt"],
    ["crossbow-heavy", "crossbow-bolt"],
    ["crossbow-light", "crossbow-bolt"],
    ["sling", "sling-bullets"],
    ["blowgun", "blowgun-needles"],
  ]);
  const equipmentIds = new Set(equipment.map((one) => one.id));
  for (const id of [...weaponIds.values(), ...AMMUNITION.values()])
    if (!equipmentIds.has(id)) fail(`no SRD equipment "${id}" for a foe to carry`);
  let carrying = 0;
  for (const creature of creatures) {
    if (creature.filters?.type !== "Humanoid" || /-form$/u.test(creature.id)) continue;
    const held = [
      ...new Set(
        creature.creature.actions.flatMap((action) => {
          const named = String(action.name ?? "")
            .toLowerCase()
            .replace(/\s*\(.*\)$/u, "");
          return weaponIds.has(named) ? [weaponIds.get(named)] : [];
        }),
      ),
    ];
    if (!held.length) continue;
    const ammunition = [...new Set(held.flatMap((id) => (AMMUNITION.has(id) ? [AMMUNITION.get(id)] : [])))];
    creature.creature.inventory = [
      ...held.map((id) => ({ item: `${EQUIPMENT_CATALOG}/${id}` })),
      ...ammunition.map((id) => ({ item: `${EQUIPMENT_CATALOG}/${id}`, count: 10 })),
    ];
    carrying += 1;
  }
  if (carrying < 30) fail(`only ${carrying} SRD humanoids carry their weapons`);
}
