// A cast of the spell another way (Magic Circle (fiends), Glyph of Warding (fire)) needs it too; a
// thing the spell then lets its caster do (Find Familiar: See through its eyes) is no cast.
{
  for (const [id, label, gp, tags, weight, summary] of MATERIAL_ITEMS) {
    if (equipment.some((entry) => entry.id === id)) fail(`equipment already has ${id}`);
    for (const tag of tags)
      if (!(handwritten.items?.tags ?? []).some((one) => one.id === tag))
        fail(`${id} carries tag ${tag}, which the items block does not declare`);
    if (!(handwritten.items?.categories ?? []).some((one) => one.id === MATERIAL_CATEGORY))
      fail(`the items block has no ${MATERIAL_CATEGORY} category`);
    equipment.push({
      id,
      label,
      summary,
      item: compact({
        category: MATERIAL_CATEGORY,
        rarity: "common",
        tags: ["mundane", ...tags].sort(),
        stats: { weight },
        cost: { amount: gp, unit: "gp" },
      }),
    });
    report.equipmentByCategory.set(MATERIAL_CATEGORY, (report.equipmentByCategory.get(MATERIAL_CATEGORY) ?? 0) + 1);
  }
  const bySpell = new Map(srdSpells.map(({ pk, fields }) => [entryId(pk), fields]));
  const priced = new Set(
    srdSpells
      .filter(
        ({ fields }) =>
          fields.material && (fields.material_cost || /\d[\d,]* ?gp\b/u.test(fields.material_specified ?? "")),
      )
      .map(({ pk }) => entryId(pk)),
  );
  for (const [id, label, gp, counts, consumed, says] of SPELL_MATERIALS) {
    const fields = bySpell.get(id) ?? fail(`no SRD spell ${id} to price the material of`);
    if (!says.test(oneLine(fields.material_specified ?? "")))
      fail(`${id}'s material no longer reads as priced: ${fields.material_specified}`);
    priced.delete(id);
    const base = spells.find((entry) => entry.id === id) ?? fail(`no spell entry ${id}`);
    const casts = spells.filter((entry) => entry === base || entry.label.startsWith(`${base.label} (`));
    // Something the package sells counts.
    const counted = equipment.filter(
      (entry) =>
        entry.item?.cost?.unit === "gp" &&
        ((counts.items ?? []).includes(`equipment/${entry.id}`) ||
          (counts.tags ?? []).some((tag) => entry.item.tags?.includes(tag))),
    );
    for (const ref of counts.items ?? [])
      if (!equipment.some((entry) => `equipment/${entry.id}` === ref))
        fail(`${id} counts ${ref}, which is not equipment`);
    if (counted.length === 0) fail(`${id}'s material has nothing to count`);
    for (const entry of casts) {
      if (!entry.mechanics) fail(`${entry.id} has no mechanics to carry its material`);
      entry.mechanics.material = compact({
        label,
        worth: { amount: gp, unit: "gp" },
        ...counts,
        consumed: consumed || undefined,
      });
    }
  }
  // Imprisonment's component is worth 500 gp for each Hit Die of its target: the Game Master's.
  priced.delete("imprisonment");
  // Simulacrum, Teleportation Circle, the SRD prints the worth with no cost field: all are above.
  if (priced.size > 0) fail(`spells with a priced material and none set: ${[...priced].join(", ")}`);
}

