// Antipathy's own fright (1.275) is "frightened" to everything else: whatever is immune to, ends,
// suppresses or helps against frightened says the same of antipathy_frightened, and an immunity keeps
// its walk away (antipathy_repelled) off too. Every list of ids naming "frightened" gains them, but
// for the conditions a zone puts on whoever stands in it (Hallow's Fear): those are the plain one only.
const FRIGHTENED_TOO = Object.freeze(["antipathy_frightened"]);
const FRIGHTENED_IMMUNE_TOO = Object.freeze(["antipathy_frightened", "antipathy_repelled"]);
function frightenedToo(value, immune = false) {
  if (Array.isArray(value)) {
    const items = value.map((item) => frightenedToo(item, immune));
    if (!items.includes("frightened")) return items;
    const extra = immune ? FRIGHTENED_IMMUNE_TOO : FRIGHTENED_TOO;
    return [...items, ...extra.filter((id) => !items.includes(id))];
  }
  if (value && typeof value === "object")
    return Object.fromEntries(
      Object.entries(value).map(([key, item]) => [
        key,
        key === "inside" && item && typeof item === "object" && !Array.isArray(item)
          ? { ...frightenedToo(item, immune), ...(item.conditions ? { conditions: item.conditions } : {}) }
          : frightenedToo(item, immune || key === "conditionImmunities" || key === "conditionImmunitiesFrom"),
      ]),
    );
  return value;
}
// "Unconscious ... The creature drops whatever it's holding, and falls prone" (0.374.0, 1.765): every
// condition that is unconsciousness by another name (dropping to 0 hit points, Sleep, Eyebite, a brass
// dragon's breath, a sprite's arrow, oil of taggit, couatl venom, Imprisonment's slumber) puts prone on
// with it, there until its holder stands.
const UNCONSCIOUS_EFFECTS = [
  "cannot-act",
  "cannot-react",
  "speed-zero",
  "attacks-against-advantage",
  "attacks-from-adjacent-critical",
];
for (const entry of combat.conditions)
  if (
    entry.condition !== "prone" &&
    // Paralyzed, which "can't move" (0.430.0) like the unconscious, stays standing.
    entry.condition !== "paralyzed" &&
    UNCONSCIOUS_EFFECTS.every((effect) => entry.effects?.includes(effect)) &&
    entry.effects.length === UNCONSCIOUS_EFFECTS.length
  )
    entry.alsoApplies = ["prone"];
const combatWritten = frightenedToo(combat);
for (const [path, value] of assets) assets.set(path, frightenedToo(value));

// The UI review (2026-10-22): a switch's two moves and a piece of gear's use in a player's words on
// the fight menu (Capability API 1.378), in place of "Turn on" and the item's name. A switch's on is
// the state its light or effect names: a hooded lantern's hood up.
const TOGGLE_WORDS = new Map([
  ["lantern-hooded", ["Raise the hood", "Lower the hood"]],
  ["lantern-of-revealing", ["Raise the hood", "Lower the hood"]],
  ["flame-tongue-greatsword", ["Ignite the blade", "Douse the blade"]],
  ["flame-tongue-longsword", ["Ignite the blade", "Douse the blade"]],
  ["flame-tongue-rapier", ["Ignite the blade", "Douse the blade"]],
  ["flame-tongue-shortsword", ["Ignite the blade", "Douse the blade"]],
  ["rod-of-lordly-might-flame-tongue", ["Ignite the blade", "Douse the blade"]],
  ["sun-blade", ["Call up the blade", "Let the blade fade"]],
  ["gem-of-brightness", ["Make it glow", "Let it go dark"]],
  ["animated-shield", ["Animate the shield", "Take the shield back"]],
]);
const GEAR_USE_TITLES = new Map([
  ["acid-vial", "Throw acid"],
  ["alchemists-fire-flask", "Throw alchemist's fire"],
  ["antitoxin-vial", "Drink antitoxin"],
  ["ball-bearings-bag-of-1000", "Scatter ball bearings"],
  ["caltrops-bag-of-20", "Scatter caltrops"],
  ["healers-kit", "Stabilize with a healer's kit"],
  ["holy-water-flask", "Throw holy water"],
  ["hunting-trap", "Set a hunting trap"],
  ["lamp-oil-flask", "Throw oil"],
  ["lantern-bullseye", "Aim the bullseye lantern"],
  ["poison-basic", "Coat a weapon with poison"],
  ["drow-poison", "Coat a weapon with drow poison"],
  ["purple-worm-poison", "Coat a weapon with purple worm poison"],
  ["serpent-venom", "Coat a weapon with serpent venom"],
  ["wyvern-poison", "Coat a weapon with wyvern poison"],
]);
{
  const seen = new Set();
  for (const [, value] of assets) {
    for (const entry of value?.entries ?? []) {
      const words = TOGGLE_WORDS.get(entry.id);
      if (words && entry.item?.toggle) {
        [entry.item.toggle.onLabel, entry.item.toggle.offLabel] = words;
        seen.add(entry.id);
      }
      const title = GEAR_USE_TITLES.get(entry.id);
      if (title && entry.item?.use) {
        entry.item.use.title = title;
        seen.add(`use:${entry.id}`);
      }
    }
  }
  for (const id of TOGGLE_WORDS.keys()) if (!seen.has(id)) fail(`${id} has no switch to name`);
  for (const id of GEAR_USE_TITLES.keys()) if (!seen.has(`use:${id}`)) fail(`${id} has no use to name`);
}

